#!/bin/bash
# Wrapper GLOBAL do emulatorlauncher: .zip com varios arquivos -> menu
# Instalado por zipmenu-hook.sh (bind mount sobre /usr/bin/emulatorlauncher),
# nao precisa de es_systems_*.cfg.

# Sistemas onde o menu NAO deve aparecer: um nome por linha neste arquivo
# (mesmo nome da pasta em /userdata/roms). Qualquer outro sistema tem o menu.
EXCL=/userdata/system/zipmenu-exclude.txt
# Extensoes de arquivo (dentro do zip) que NAO aparecem na lista: uma por linha, sem ponto (ex.: txt). Editado pela janela Add/Remove.
HIDEEXT=/userdata/system/zipmenu-hide-ext.txt

SELF=/userdata/system/zipmenu-launch.sh
CELLCACHE=/userdata/system/zipmenu-cell.cache   # "altura largura" da celula do xterm em pixels (gravado pelo menu)
REAL=/tmp/emulatorlauncher.real
[ -s "$REAL" ] || REAL=emulatorlauncher   # fallback (sem hook instalado)

# modo menu (roda dentro do xterm) - menu proprio em ANSI, sem dialog
if [ "$1" = "--pick" ]; then
  ZIP="$2"; OUT="$3"
  # ALLF = todos os arquivos do zip (caminho completo). O menu mostra UMA pasta por vez (CUR = pasta atual, "" = raiz,
  # senao "A/" ou "A/B/"): primeiro as subpastas (com "/" no fim), depois os arquivos daquela pasta.
  # Dentro de uma pasta aparece "../" no topo para BACK (tambem: seta esquerda ou Backspace; seta direita entra na pasta).
  mapfile -t ALLALL < <(unzip -Z1 "$ZIP" | grep -v '/$' | LC_ALL=C sort -f)
  # ALLF = ALLALL sem as extensoes ocultas (coluna FILES da janela Add/Remove). Se tudo ficasse oculto, ignora o filtro.
  apply_filter() {
    local p e
    local -A H=()
    if [ -s "$HIDEEXT" ]; then
      while IFS= read -r e || [ -n "$e" ]; do
        e="${e//[$'\r ']/}"; e="${e#.}"; e="${e,,}"
        [ -n "$e" ] && H[$e]=1
      done < "$HIDEEXT"
    fi
    ALLF=()
    for p in "${ALLALL[@]}"; do
      e="${p##*/}"
      if [[ "$e" == *.* ]]; then e="${e##*.}"; e="${e,,}"; [ -n "${H[$e]}" ] && continue; fi
      ALLF+=("$p")
    done
    [ "${#ALLF[@]}" -gt 0 ] || ALLF=("${ALLALL[@]}")
  }
  apply_filter
  CUR=""
  FILES=(); FULL=(); ISDIR=(); N=0
  build_list() {
    local p rest d f
    local -A SD=()
    local -a dirs=() files=()
    FILES=(); FULL=(); ISDIR=()
    for p in "${ALLF[@]}"; do
      if [ -n "$CUR" ] && [ "${p#"$CUR"}" = "$p" ]; then continue; fi
      rest="${p#"$CUR"}"
      if [[ "$rest" == */* ]]; then
        d="${rest%%/*}"
        if [ -z "${SD[$d]}" ]; then SD[$d]=1; dirs+=("$d"); fi
      else
        files+=("$rest")
      fi
    done
    if [ -n "$CUR" ]; then FILES+=("../"); FULL+=(".."); ISDIR+=(1); fi
    for d in "${dirs[@]}";  do FILES+=("$d/"); FULL+=("$d"); ISDIR+=(1); done
    for f in "${files[@]}"; do FILES+=("$f");  FULL+=("$CUR$f"); ISDIR+=(0); done
    N=${#FILES[@]}
  }
  nav_up() {   # sobe uma pasta e deixa selecionada a pasta de onde saiu
    [ -n "$CUR" ] || return 1
    local c="${CUR%/}" last i
    last="${c##*/}/"
    if [[ "$c" == */* ]]; then CUR="${c%/*}/"; else CUR=""; fi
    build_list; SEL=0; TOP=0
    for i in "${!FILES[@]}"; do if [ "${FILES[i]}" = "$last" ]; then SEL=$i; break; fi; done
    MQ_SEL=-1; return 0
  }
  nav_down() {   # entra na pasta selecionada
    [ "${ISDIR[SEL]}" = 1 ] || return 1
    if [ "${FULL[SEL]}" = ".." ]; then nav_up; return 0; fi
    CUR="$CUR${FULL[SEL]}/"
    build_list; SEL=0; TOP=0; MQ_SEL=-1; return 0
  }
  build_list

  # janela 4:3 em PIXELS. A celula do terminal nao e 2:1 exata (com a fonte Monospace fica ~1.9:1),
  # entao o xterm e perguntado o tamanho real da celula em pixels (CSI 16 t -> ESC [ 6 ; altura ; largura t).
  # Se nao responder, assume 2:1 (AR=200).
  AR=200
  cell_probe() {
    local old resp="" CH="" CW=""
    old=$(stty -g 2>/dev/null) || return
    stty -icanon -echo 2>/dev/null
    printf '\e[16t'
    IFS= read -r -d t -t 0.5 resp
    stty "$old" 2>/dev/null
    resp="${resp##*[}"
    case "$resp" in
      6\;[0-9]*\;[0-9]*) IFS=';' read -r _ CH CW <<<"$resp" ;;
    esac
    if [ "${CH:-0}" -gt 0 ] && [ "${CW:-0}" -gt 0 ] 2>/dev/null; then
      AR=$(( CH*100/CW ))
      echo "$CH $CW" > "$CELLCACHE" 2>/dev/null   # usado na proxima abertura para o xterm ja nascer do tamanho da tela
      [ "$AR" -lt 120 ] && AR=120
      [ "$AR" -gt 300 ] && AR=300
    fi
  }
  cell_probe
  # espera o xterm terminar de ir para tela cheia antes de desenhar o 1o quadro (tamanho estavel por ~0.3s, max 3s)
  _last=""; _same=0
  for _i in $(seq 1 60); do
    _now=$(stty size 2>/dev/null)
    if [ -n "$_now" ] && [ "$_now" = "$_last" ]; then _same=$((_same+1)); else _same=0; fi
    _last="$_now"
    [ "$_same" -ge 6 ] && break
    sleep 0.05
  done
  # Tamanho = 80% da tela +40% (112%), limitado para caber com 1 linha/coluna de margem.
  # Recalcula se o terminal mudar de tamanho (xterm -fullscreen redimensiona depois de abrir).
  # cabecalho: 0 = titulo normal (1 linha, como antes); 1 = titulo em altura dupla (2x2, grande demais; o terminal so
  # sabe 1x ou 2x por linha, via ESC#3/ESC#4). O "pouquinho maior" vem do tamanho da fonte do xterm (FONT_SZ, mais abaixo).
  HDR_BIG=0

  layout() {
    R=""; C=""
    read -r R C < <(stty size 2>/dev/null)
    if [ "${R:-0}" -lt 1 ] || [ "${C:-0}" -lt 1 ]; then
      R=$(tput lines 2>/dev/null || echo 40); C=$(tput cols 2>/dev/null || echo 120)
    fi
    # W = H * 4/3 * (altura_da_celula / largura_da_celula): AR = altura/largura da celula x100
    H=$((R*112/100)); W=$(( (H*4*AR+150)/300 ))
    if [ "$H" -gt $((R-2)) ]; then H=$((R-2)); W=$(( (H*4*AR+150)/300 )); fi
    if [ "$W" -gt $((C-2)) ]; then W=$((C-2)); H=$(( (W*300+2*AR)/(4*AR) )); fi
    [ "$H" -lt 8 ] && H=8
    HB=1; [ "$HDR_BIG" = 1 ] && [ "$H" -ge 10 ] && HB=2     # linhas da barra do topo
    [ "$HB" = 2 ] && W=$((W/2*2))                          # linha de dupla largura: W par e X0 impar fazem a barra casar com a janela
    Y0=$(( (R-H)/2 + 1 )); X0=$(( (C-W)/2 + 1 ))
    [ "$HB" = 2 ] && [ $((X0%2)) -eq 0 ] && X0=$((X0+1))
    LOFF=$((HB+1)); L=$((H-5-LOFF)); IW=$((W-2))   # 1a linha da lista (+LOFF) / linhas da lista (folga em cima, e folga + linha dos botoes embaixo) / largura interna
  }
  layout

  at() { printf '\e[%d;%dH' "$1" "$2"; }

  # tarja de fundo (azul escuro) da linha dos botoes START/BACK/Add-Remove + porcentagem. Para mudar a cor: 48;2;R;G;B
  BAR_BG="48;2;0;0;60"

  frame() {
    local r T col
    printf '\e[0;97;40m\e[2J\e[?25l'
    for ((r=1; r<=R; r++)); do printf '\e[%d;1H\e#5' "$r"; done   # todas as linhas em largura normal (limpa restos de dupla altura de um layout anterior)
    # barra azul do topo (titulo branco) e 3 barras azuis embaixo (a do meio tem os botoes e as bolinhas)
    for r in $([ "$HB" = 1 ] && echo 0) $((H-3)) $((H-2)) $((H-1)); do
      at $((Y0+r)) "$X0"; printf '\e[0;97;44m\e[%dX' "$W"
    done
    for ((r=HB; r<=H-4; r++)); do
      at $((Y0+r)) "$X0"; printf '\e[44m \e[40m'
      at $((Y0+r)) $((X0+W-1)); printf '\e[44m \e[40m'
    done
    T="${ZIP#/userdata/roms}"
    FNAME="${T##*/}"; DNAME="${T%/*}/"; DNAME="${DNAME^^}"
    T=" ${DNAME}${FNAME} "   # ex.: " /MEGADRIVE/hacks.zip "
    if [ "$HB" = 2 ]; then
      # titulo em ALTURA DUPLA: 2 linhas (ESC#3 = metade de cima, ESC#4 = metade de baixo) com o mesmo texto. Nessas linhas cada
      # coluna vale 2 colunas da tela e a barra azul e o texto sao enderecados em colunas "logicas" (metade da posicao real).
      local ca=$(( (X0+1)/2 )) nb=$(( W/2 ))
      [ ${#T} -gt $((nb-2)) ] && T=" ...${T: -$((nb-8))}"   # muito longo: corta o comeco
      col=$(( ca + (nb - ${#T}) / 2 ))
      PRE="${T% }"; PRE="${PRE%"$FNAME"}"
      for r in 0 1; do
        at $((Y0+r)) 1; if [ "$r" = 0 ]; then printf '\e#3'; else printf '\e#4'; fi
        at $((Y0+r)) "$ca"; printf '\e[0;97;44m\e[%dX' "$nb"
        at $((Y0+r)) "$col"; printf '\e[5;1;92;44m%s\e[0;25;1;97;44m%s ' "$PRE" "$FNAME"
      done
    else
      [ ${#T} -gt $((W-2)) ] && T=" ...${T: -$((W-8))}"   # muito longo: corta o comeco
      col=$(( X0 + (W - ${#T}) / 2 ))
      PRE="${T% }"; PRE="${PRE%"$FNAME"}"   # tudo antes do nome do arquivo, sem o espaco final
      at "$Y0" "$col"; printf '\e[5;1;92;44m%s\e[0;25;1;97;44m%s ' "$PRE" "$FNAME"
    fi
    # botoes START / BACK e a porcentagem ficam na AREA PRETA, na ultima linha da lista (logo acima da barra azul de baixo)
    T="< START(A) >      < BACK(B) >      < ADD/REMOVE(X) >"   # so para medir/centralizar (sem cores)
    col=$(( X0 + (W - ${#T}) / 2 ))
    BROW=$((Y0+H-4))
    at "$BROW" $((X0+1)); printf '\e[0;97;%sm\e[%dX' "$BAR_BG" "$IW"   # tarja azul escura de ponta a ponta (dentro das bordas)
    at "$BROW" "$col"
    printf '\e[1;92;%sm< \e[1;38;2;170;100;255;%smSTART(A)\e[1;92;%sm >      < \e[1;38;2;170;100;255;%smBACK(B)\e[1;92;%sm >      < \e[1;38;2;170;100;255;%smADD/REMOVE(X)\e[1;92;%sm >' "$BAR_BG" "$BAR_BG" "$BAR_BG" "$BAR_BG" "$BAR_BG" "$BAR_BG" "$BAR_BG"
    PCOL=$(( X0 + W - 6 ))   # coluna da porcentagem/spinner, alinhada a direita (na mesma linha dos botoes)
    # a barra azul de baixo agora so tem a animacao: UMA trilha de ponta a ponta (TRK2/TW2 = trilha da direita, vazia)
    TRK1=$X0; TW1=$W
    TRK2=$((X0+W)); TW2=0
    TRK_OK=0
    if [ "$TW1" -ge 4 ]; then TRK_OK=1; fi
    MODE=0; PP=-4; CP=0; RP=0; AP=-7; FP=0; MOUTH=0; WAIT=0; BT=0; FLG=0
    FA=(1 1 1); FEX=(0 0 0); BX=(); BCD=0; FGE=10; SGE=20; SP=0
    draw_scan
  }

  # desenha uma linha da lista (1a letra verde; tarja da selecao azul escuro)
  # reserva a ultima coluna de IW para a scrollbar (nao faz parte do texto)
  row() {
    local r="$1" idx="$2" sel="$3" full name first rest body ext ext_at=-1 off=0 base
    at "$r" $((X0+1))
    if [ "$sel" = 1 ]; then printf '\e[1;97;%sm\e[%dX' "$SEL_BG" "$IW"; else printf '\e[0;97;40m\e[%dX' "$IW"; fi
    [ "$idx" -ge "$N" ] && return
    full="${FILES[$idx]}"
    if [ "$sel" = 1 ] && [ "${#full}" -gt $((IW-4)) ]; then
      off=$MQ_OFF
      name="${full:$off:$((IW-4))}"   # item selecionado e grande: mostra a janela rolada (marquee)
    else
      name="${full:0:$((IW-4))}"
    fi
    # extensao (.ext) em roxo: posicao dela dentro do trecho visivel
    base="${full%.*}"
    if [ "$base" != "$full" ] && [ -n "$base" ] && [ "${full: -1}" != "/" ]; then
      ext_at=$(( ${#base} - off ))
    fi
    first="${name:0:1}"; rest="${name:1}"
    body="$rest"; ext=""
    if [ "$ext_at" -ge 0 ] && [ "$ext_at" -lt "${#name}" ]; then
      [ "$ext_at" -lt 1 ] && ext_at=1
      body="${name:1:ext_at-1}"; ext="${name:ext_at}"
    fi
    at "$r" $((X0+2))
    if [ "$sel" = 1 ]; then
      printf '\e[1;97;%sm%s\e[1;97;%sm%s\e[0;38;2;230;210;90;%sm%s' "$SEL_BG" "$first" "$SEL_BG" "$body" "$SEL_BG" "$ext"
    else
      printf '\e[1;92;40m%s\e[0;97;40m%s\e[0;38;2;230;210;90;40m%s' "$first" "$body" "$ext"
    fi
  }

  # thumb da scrollbar (coluna da direita da lista), independente da selecao
  scrollbar_cell() {
    local k="$1" row col ch
    row=$((Y0+LOFF+k)); col=$((X0+IW))
    if [ "$k" -ge "$THUMB_POS" ] && [ "$k" -lt $((THUMB_POS+THUMB_H)) ]; then
      ch='\xe2\x96\x88'   # bloco cheio (thumb)
      printf '\e[%d;%dH\e[1;97;40m%b' "$row" "$col" "$ch"
    else
      ch='\xe2\x96\x91'   # bloco claro (trilho)
      printf '\e[%d;%dH\e[0;34;40m%b' "$row" "$col" "$ch"
    fi
  }

  # barra de selecao pulsante: o fundo da linha selecionada faz uma transicao SUAVE e lenta entre roxo
  # escuro e verde escuro (um passo a cada 0.3s; PSTEPS passos para ir e PSTEPS para BACK = ciclo de
  # 2*PSTEPS*0.3s, hoje 4.8s). Aumente PSTEPS para ficar ainda mais lento.
  # a seta (coluna livre entre a borda e o texto) acompanha a mesma cor
  PULSE=0; PSTEPS=8
  SEL_BG="48;2;22;0;38"   # roxo escuro (estado inicial)
  pulse_tick() {
    local t
    PULSE=$(( (PULSE+1) % (2*PSTEPS) ))
    if [ "$PULSE" -le "$PSTEPS" ]; then t=$PULSE; else t=$((2*PSTEPS-PULSE)); fi
    # roxo (22,0,38) <-> verde (0,35,0)
    SEL_BG="48;2;$(( 22-22*t/PSTEPS ));$(( 35*t/PSTEPS ));$(( 38-38*t/PSTEPS ))"
    local k=$((SEL-TOP))
    [ "$k" -lt 0 ] || [ "$k" -ge "$L" ] && return
    row $((Y0+LOFF+k)) "$SEL" 1
    scrollbar_cell "$k"
    draw_pulse
  }
  draw_pulse() {
    local k=$((SEL-TOP)) row col
    [ "$k" -lt 0 ] || [ "$k" -ge "$L" ] && return
    row=$((Y0+LOFF+k)); col=$((X0+1))
    printf '\e[%d;%dH\e[1;97;%sm\xe2\x96\xb6' "$row" "$col" "$SEL_BG"   # ▶
  }

  # ===== Sprites coloridos em braille (2x4 pontos por celula) =====
  # Cada celula do terminal tem UMA cor de frente (a do primeiro pixel aceso nela) e fundo azul da barra,
  # exceto os "olhos" dos fantasmas, que usam fundo proprio. Letras dos pixels: '.' = apagado, outra = cor (PAL).
  # Sprite com 3 linhas de celulas (12 pixels de altura); NC colunas de celulas (2 pixels cada).
  # (bytes UTF-8 explicitos para nao depender do locale)
  declare -A PAL=(
    [Y]="1;38;2;235;175;0;44"                      # Pac-Man
    [r]="1;38;2;255;40;40;44"                      # fantasma 1: vermelho
    [m]="1;38;2;255;150;205;44"                    # fantasma 2: rosa
    [i]="1;38;2;125;215;230;44"                    # fantasma 3: azul claro (cor do fantasma da imagem)
    [e]="1;38;2;60;140;255;44"                     # bolinha do olho dos fantasmas (azul), direto sobre o fundo azul da barra
    [o]="1;38;2;255;150;40;44"                     # alienigena 1: laranja
    [u]="1;38;2;60;220;230;44"                     # alienigena 2: ciano
    [p]="1;38;2;255;110;170;44"                    # alienigena 3: rosa
    [k]="1;38;2;175;175;185;44"                    # pneus (cinza claro)
    [t]="1;38;2;70;70;80;44"                    # rodinhas dos carros (cinza escuro; para clarear/escurecer mude o 70;70;80)
    [c]="1;38;2;255;250;160;44"                    # cockpit
    [X]="1;38;2;25;25;30;44"                       # escapamentos dos carros (preto)
    [B]="1;38;2;60;140;255;44"                     # carro azul
    [R]="1;38;2;255;30;40;44"                      # carro vermelho
    [z]="1;38;2;255;250;170;44"                    # fumaca do carro vermelho (amarelo palido)
    [s]="1;38;2;248;0;0;44"                        # desenho "S + bandeira": o S vermelho
    [w]="1;38;2;240;240;72;44"                     # desenho "S + bandeira": a bandeira amarela
    [f]="1;38;2;110;165;252;44"                    # ventiladores: azul claro
    [W]="1;38;2;255;255;255;44"                    # ventiladores / nave: branco
    [n]="1;38;2;106;138;244;44"                    # nave: corpo azul
    [q]="1;38;2;252;131;116;44"                    # nave: nariz rosa
    [a]="1;38;2;108;186;253;44"                    # nave: aletas ciano
    [x]="1;38;2;232;52;43;44"                      # nave: listra vermelha (ponta)
  )
  mk_spr() {   # NOME NC linha0..linha11
    local nm="$1" nc="$2" rows rr cx py px c k s b cls bn n
    local -A cnt=()
    shift 2; rows=("$@")
    local -n SAVED="${nm}_ROWS"; SAVED=("${rows[@]}")   # guarda as linhas (para gerar a versao deslocada de 1 pixel, mk_half)
    if [ "$MK_MIN" = 1 ]; then   # versao deslocada: conta os pixels de cada cor no sprite inteiro
      for c in "${rows[@]}"; do
        for ((px=0; px<${#c}; px++)); do k="${c:px:1}"; [ "$k" = "." ] || cnt[$k]=$(( ${cnt[$k]:-0} + 1 )); done
      done
    fi
    for ((rr=0; rr<3; rr++)); do
      for ((cx=0; cx<nc; cx++)); do
        b=0; cls=""
        for ((py=0; py<4; py++)); do
          for ((px=0; px<2; px++)); do
            c="${rows[rr*4+py]:cx*2+px:1}"
            if [ -z "$c" ] || [ "$c" = "." ]; then continue; fi
            if [ "$MK_MIN" = 1 ]; then   # celula com 2 cores (so na versao deslocada): ganha a cor MENOS usada (olho, cabine, chama...)
              n=${cnt[$c]}
              if [ -z "$cls" ] || [ "$n" -lt "$bn" ]; then cls="$c"; bn=$n; fi
            else
              [ -z "$cls" ] && cls="$c"
            fi
            case "$px,$py" in
              0,0) k=1 ;; 0,1) k=2 ;; 0,2) k=4 ;; 0,3) k=64 ;;
              1,0) k=8 ;; 1,1) k=16 ;; 1,2) k=32 ;; 1,3) k=128 ;;
            esac
            b=$((b|k))
          done
        done
        if [ "$b" -gt 0 ]; then
          printf -v s '\\x%02x\\x%02x\\x%02x' 226 $((160|(b>>6))) $((128|(b&63)))
        else
          s=" "
        fi
        printf -v "${nm}_G[$((rr*nc+cx))]" "$s"   # (formato, nao %s: converte os \\xNN em bytes)
        printf -v "${nm}_C[$((rr*nc+cx))]" '%s' "$cls"
      done
    done
  }

  # TODOS os sprites tem o tamanho do Pac-Man original: 8x8 pixels = 4 colunas x 3 linhas de celulas
  # (as 8 linhas de pixels ficam no meio das 12, com 2 linhas vazias em cima e embaixo).
  mk8() { local nm="$1"; shift; mk_spr "$nm" 4 "........" "........" "$@" "........" "........"; }

  # Pac-Man: boca aberta para a direita / fechada
  mk8 PAC_R "..YYYY.." ".YYYYY.." "YYYYY..." "YYYY...." "YYYY...." "YYYYY..." ".YYYYY.." "..YYYY.."
  mk8 PAC_C "..YYYY.." ".YYYYYY." "YYYYYYYY" "YYYYYYYY" "YYYYYYYY" "YYYYYYYY" ".YYYYYY." "..YYYY.."
  # 3 fantasminhas que perseguem o Pac-Man (cabeca redonda, "pes" ondulados, como o fantasma da imagem), um de cada cor:
  # vermelho (o da frente), rosa e azul claro. Corpo de pontos espacados (braille), como os alienigenas. Olhos so com
  # a bolinha azul, do lado direito (olhando para onde ele corre); piscar = SO as 4 bolinhas do olho somem (o corpo nao muda).
  # g = corpo (trocado pela cor de cada fantasma), e = pupila.
  GH_OP=("..gggg.." ".gggggg." "gg....gg" "gg.e.egg" "gg.e.egg" "gg....gg" "gggggggg" "gg.gg.gg")
  GH_SH=("${GH_OP[@]//e/.}")                  # piscando: igual ao aberto, mas sem as 4 bolinhas (e) do olho
  mk8 M1_O "${GH_OP[@]//g/r}";  mk8 M1_S "${GH_SH[@]//g/r}"
  mk8 M2_O "${GH_OP[@]//g/m}";  mk8 M2_S "${GH_SH[@]//g/m}"
  mk8 M3_O "${GH_OP[@]//g/i}";  mk8 M3_S "${GH_SH[@]//g/i}"
  # Carros de corrida vistos de cima, virados para a esquerda: azul e vermelho
  # 10 pixels de largura (5 colunas): 8 do carro + 2 escapamentos pretos (X) saindo atras (a direita), um de cada lado
  CAR_T=("..tt..tt.." "..tt..tt.." "..BB..BBXX" "BBBBccBB.." "BBBBccBB.." "..BB..BBXX" "..tt..tt.." "..tt..tt..")
  mk_spr CAR_B 5 "........" "........" "${CAR_T[@]}" "........" "........"
  CAR_RT=("${CAR_T[@]//B/R}")
  mk_spr CAR_R 5 "........" "........" "${CAR_RT[@]}" "........" "........"
  # baforada de fumaca do carro vermelho (8x8, 4 colunas x 3 linhas): nuvem amarelo palido com "rachaduras" (buracos)
  mk8 SMOKE "..zzz..." ".zzzzzz." "zzz.zzzz" "zzzzz.zz" "zz.zzzzz" "zzzzzzz." ".zzz.zz." "..zzzz.."
  # desenho "S + bandeira" (12x8 pixels, 6 colunas x 3 linhas de celulas, igual ao da imagem): fica centrado entre a borda esquerda
  # e o botao START durante a passagem dos carros e some quando o carro azul encosta nele.
  # (s = vermelho, w = amarelo; nenhuma celula mistura as duas cores)
  mk_spr FLAG 6 "............" "............" ".sss..w....." "s...s.ww...." "s.....wwww.." ".sss..wwwwww" "....s.wwww.." "s...s.ww...." ".sss..w....." "......www..." "............" "............"

  # 3 space invaders (lula laranja, caranguejo ciano e polvo rosa), cada um com 2 quadros de movimento (pernas) e
  # olhos que piscam (x = corpo, e = olho: aberto = buraco, fechado = preenchido). Cada um tem seu proprio tamanho
  # (lula 10x9, caranguejo 12x9, polvo 14x8 pixels) e fica centrado nas 3 linhas de celulas.
  mk_al() {   # NOME NC COR linhas...  (gera NOME_O = olho aberto e NOME_S = olho fechado)
    local nm="$1" nc="$2" c="$3" n w s i top bot blank O=() S=()
    shift 3; n=$#; w=$((nc*2))
    top=$(( (12-n)/2 )); bot=$(( 12-n-top ))
    printf -v blank '%*s' "$w" ''; blank="${blank// /.}"
    for ((i=0; i<top; i++)); do O+=("$blank"); S+=("$blank"); done
    for s in "$@"; do
      while [ ${#s} -lt "$w" ]; do s+="."; done
      s="${s//x/$c}"; O+=("${s//e/.}"); S+=("${s//e/$c}")
    done
    for ((i=0; i<bot; i++)); do O+=("$blank"); S+=("$blank"); done
    mk_spr "${nm}_O" "$nc" "${O[@]}"; mk_spr "${nm}_S" "$nc" "${S[@]}"
  }
  # lula (laranja)
  mk_al AL1_1 5 o "...xxx..." "..xxxxx.." ".xxxxxxx." "xxexxxexx" "xxxxxxxxx" "..xx.xx.." "..xx.xx.." ".x.xxx.x." "x.xx.xx.x"
  mk_al AL1_2 5 o "...xxx..." "..xxxxx.." ".xxxxxxx." "xxexxxexx" "xxxxxxxxx" "..xx.xx.." ".x.xxx.x." "x..xxx..x" ".x.x.x.x."
  # caranguejo (ciano)
  mk_al AL2_1 6 u "..x......x.." "x..x....x..x" "x.xxxxxxxx.x" "xxxexxxxexxx" "xxxxxxxxxxxx" ".xxxxxxxxxx." ".xxxxxxxxxx." "..x......x.." ".x........x."
  mk_al AL2_2 6 u "..x......x.." "x..x....x..x" "x.xxxxxxxx.x" "xxxexxxxexxx" "xxxxxxxxxxxx" ".xxxxxxxxxx." ".xxxxxxxxxx." ".x.x....x.x." "x.x......x.x"
  # polvo (rosa)
  mk_al AL3_1 7 p "....xxxxx...." ".xxxxxxxxxxx." "xxxxxxxxxxxxx" "xxxeexxxeexxx" "xxxxxxxxxxxxx" "xxxxxxxxxxxxx" "...xxxxxxx..." "..xx.xxx.xx.."
  mk_al AL3_2 7 p "....xxxxx...." ".xxxxxxxxxxx." "xxxxxxxxxxxxx" "xxxeexxxeexxx" "xxxxxxxxxxxxx" "xxxxxxxxxxxxx" "...xxxxxxx..." ".xx..xxx..xx."

  # 3 ventiladores (8x8 pixels = 4 colunas x 3 linhas de celulas, o mesmo tamanho do Pac-Man): 2 quadros de giro (FAN_0 / FAN_1),
  # azul claro com um bloco branco que marca a pa (ao alternar os quadros o ventilador parece girar).
  mk8 FAN_0 "..ffff.." ".WWff.f." "fWWfffff" "ffffffff" "fffff.ff" ".ffffff." ".ffffff." "..ffff.."
  mk8 FAN_1 "..ffff.." ".ffffff." "ffffffff" "fffff.ff" "ffffffff" "fffffWWf" ".ffffWW." "..ffff.."
  # explosao dos ventiladores (8x8, 3 quadros): clarao, bola de fogo e fagulhas se dispersando
  mk8 EXP_0 "........" "........" "...cc..." "..cWWc.." "..cWWc.." "...cc..." "........" "........"
  mk8 EXP_1 "...xx..." "..oooo.." ".ooccoo." "xoccWcox" "xoccWcox" ".ooccoo." "..oooo.." "...xx..."
  mk8 EXP_2 "x......x" "..o..o.." ".o....o." "........" "........" ".o....o." "..o..o.." "x......x"
  BUL=$'\xe2\xa3\xa4'     # tiro: tracinho 4x2 pontos (2 colunas), na altura do nariz da nave
  # a nave: Vic Viper do Gradius, desenhada a partir da imagem de referencia e espelhada (nariz para a esquerda, que e para onde
  # ela anda). Tem a MESMA ALTURA do Pac-Man (8 pixels = 3 linhas de celulas); a largura e 16 pixels (8 colunas) porque a
  # nave e comprida (~2:1): asa de cima varrida para tras, fuselagem longa com o nariz fino, listra laranja/vermelha,
  # aletas ciano atras e asa de baixo menor. (W = branco, k = cinza, o = laranja, x = vermelho, a = ciano)
  mk_spr SHIP 8 "................" "................" \
    "............WWWW" \
    "..........WWWWW." \
    "........WWWWaa.." \
    "...xoooWWWWWWW.." \
    "WWWWWWWWWWWWaaa." \
    "..WWWWWWWWWaaa.." \
    ".....kkkkkkkk..." \
    ".......kkkk....." \
    "................" "................"
  # fogo do motor (2 colunas, atras = a direita da nave): fogo VERMELHO do escapamento (vermelho-alaranjado na base e vermelho na
  # ponta), com 3 quadros que alternam rapido para dar o movimento de chama.
  mk_spr FLM_0 2 "...." "...." "...." "...." "...." "..R." "xxRR" "xxRR" "..R." "...." "...." "...."
  mk_spr FLM_1 2 "...." "...." "...." "...." "...." "...." "xxR." "xxR." "...." "...." "...." "...."
  mk_spr FLM_2 2 "...." "...." "...." "...." "...." "...." "xxRR" "xxR." "..R." "...." "...." "...."

  DOT=$'\xe2\xa0\xb6'      # ⠶ U+2836 (bolinha 2x2 pontos, centrada na altura da celula)
  make_dots() {   # largura -> bolinha nas colunas pares
    local w="$1" i s=""
    for ((i=0; i<w; i++)); do
      if [ $((i%2)) -eq 0 ]; then s+="$DOT"; else s+=" "; fi
    done
    printf '%s' "$s"
  }
  # coluna da tela para a posicao PP da trilha virtual (esquerda + direita, os botoes sao "pulados")
  cell_col() { if [ "$1" -lt "$TW1" ]; then CC=$((TRK1+$1)); else CC=$((TRK2+$1-TW1)); fi; }
  # desenha o sprite NOME (NC colunas) com a coluna da esquerda na posicao V da trilha virtual
  draw_spr() {
    local nm="$1" nc="$2" v0="$3" cx v rr i
    local -n SG="${nm}_G" SC="${nm}_C"
    for ((cx=0; cx<nc; cx++)); do
      v=$((v0+cx))
      if [ "$v" -lt 0 ] || [ "$v" -ge $((TW1+TW2)) ]; then continue; fi
      cell_col "$v"
      for ((rr=0; rr<3; rr++)); do
        i=$((rr*nc+cx))
        at $((Y0+H-3+rr)) "$CC"
        if [ -n "${SC[i]}" ]; then printf '\e[%sm%s' "${PAL[${SC[i]}]}" "${SG[i]}"; else printf '\e[0;97;44m '; fi
      done
    done
  }
  # ===== movimento suave =====
  # A animacao anda 1 coluna (2 pixels) a cada 0.1s. Para ficar lisa, entre dois passos o sprite e redesenhado 1 pixel
  # (meia coluna) adiante, na direcao do movimento (20 quadros por segundo em vez de 10). A versao deslocada de cada sprite
  # (NOME_h, 1 coluna mais larga) e gerada na primeira vez que e usada.
  MK_MIN=0; HALF=0; SUB=0
  declare -A HDONE=()
  mk_half() {   # NOME NC -> cria NOME_h: o mesmo sprite deslocado 1 pixel para a direita, com NC+1 colunas
    local nm="$1" nc="$2" r i
    local -n SRC="${nm}_ROWS"
    local -a nr=()
    for r in "${SRC[@]}"; do nr+=(".$r"); done
    MK_MIN=1; mk_spr "${nm}_h" $((nc+1)) "${nr[@]}"; MK_MIN=0
  }
  draw_mv() {   # NOME NC POS DIR(R|L): sprite que anda; no meio passo desenha deslocado (para a direita: POS+0,5; para a esquerda: POS-0,5)
    local nm="$1" nc="$2" pos="$3" dir="$4"
    if [ "$HALF" = 1 ]; then
      if [ -z "${HDONE[$nm]}" ]; then mk_half "$nm" "$nc"; HDONE[$nm]=1; fi
      [ "$dir" = L ] && pos=$((pos-1))
      draw_spr "${nm}_h" $((nc+1)) "$pos"
    else
      draw_spr "$nm" "$nc" "$pos"
    fi
  }
  draw_bul() {   # tiro: so a linha do meio das 3 (nao apaga o que estiver atras, como a explosao); 2 colunas a partir de V
    local v cx
    for ((cx=0; cx<2; cx++)); do
      v=$(($1+cx))
      if [ "$v" -lt 0 ] || [ "$v" -ge $((TW1+TW2)) ]; then continue; fi
      cell_col "$v"; at $((Y0+H-2)) "$CC"; printf '\e[%sm%s' "${PAL[c]}" "$BUL"
    done
  }
  erase_mid() {   # apaga so a linha do meio da coluna V (onde passa o tiro)
    [ "$1" -ge 0 ] && [ "$1" -lt $((TW1+TW2)) ] || return
    cell_col "$1"; at $((Y0+H-2)) "$CC"; printf '\e[0;97;44m '
  }
  erase_cell() {
    [ "$1" -ge 0 ] && [ "$1" -lt $((TW1+TW2)) ] || return
    cell_col "$1"
    at $((Y0+H-3)) "$CC"; printf '\e[0;97;44m '
    at $((Y0+H-2)) "$CC"; printf '\e[0;97;44m '
    at $((Y0+H-1)) "$CC"; printf '\e[0;97;44m '
  }
  draw_dots() {
    at $((Y0+H-2)) "$TRK1"; printf '\e[1;97;44m%s' "$DOTS1"
    [ "$TW2" -gt 0 ] && { at $((Y0+H-2)) "$TRK2"; printf '\e[1;97;44m%s' "$DOTS2"; }
  }
  clear_track() {   # trilhas vazias (sem bolinhas) para a passagem dos carros
    local r
    for r in $((H-3)) $((H-2)) $((H-1)); do
      at $((Y0+r)) "$TRK1"; printf '\e[0;97;44m\e[%dX' "$TW1"
      [ "$TW2" -gt 0 ] && { at $((Y0+r)) "$TRK2"; printf '\e[0;97;44m\e[%dX' "$TW2"; }
    done
  }

  # Animacao em 3 passagens, em loop (tudo na mesma faixa de 3 linhas do Pac-Man):
  #  MODE 0: o Pac-Man entra pela esquerda comendo as bolinhas (pulando os botoes) com os 3 fantasmas
  #          (de olhos que piscam) correndo atras dele; todos saem pela direita.
  #  MODE 1: sem bolinhas, o carro azul e o vermelho (com bastante espaco entre eles, na mesma velocidade
  #          do Pac-Man) cruzam da direita para a esquerda.
  #  MODE 2: os 3 space invaders (2 quadros de movimento e olhos que piscam) cruzam da esquerda para a direita.
  #  MODE 3: os 3 ventiladores (giram alternando 2 quadros) entram da direita para a esquerda, com a nave logo atras.
  #          A nave NUNCA para: anda um pouco mais rapido que os ventiladores (alcanca-os), solta tiros e acerta um
  #          ventilador apos o outro (o mais proximo primeiro), cada um explode; depois segue ate sair da tela pela
  #          esquerda, as bolinhas reaparecem e recomeca.
  # PP = coluna da esquerda do Pac-Man; CP / RP = coluna da esquerda do carro azul / vermelho;
  # AP = coluna da esquerda do alienigena da frente (o outro vem AGAP atras).
  MOFF=18     # distancia (colunas) entre a esquerda do 1o fantasma e a do Pac-Man (cada sprite tem 4 colunas)
  MGAP=10     # distancia entre um monstro e o seguinte
  CSTEP=1     # colunas por tick (0.1s) dos carros: a mesma velocidade do Pac-Man e dos monstros
  RSTEP=1
  SMOKE_N=3       # o carro vermelho solta SOMENTE 3 baforadas de fumaca (no total, por passagem)
  SMOKE_BLINKS=3  # cada baforada da 3 piscadas e some
  SMOKE_BLINK=3   # ticks (0.1s) aceso / ticks apagado em cada piscada (3 = 0.3s aceso + 0.3s apagado)
  SMOKE_LIFE=$((SMOKE_BLINKS*2*SMOKE_BLINK))   # vida de cada baforada em ticks (3 piscadas x (aceso+apagado) = 18 ticks = 1,8s)
  SMOKE_EVERY=8   # ticks entre uma baforada e a seguinte
  SMK_V=(); SMK_L=(); SMK_CD=0; SMK_N=0   # baforadas: coluna da esquerda na trilha / vida restante; contagem para a proxima; quantas ja sairam
  RMIN=6      # distancia minima entre a esquerda do vermelho e a do azul
  RGAP=26     # distancia entre os dois carros (cada um tem 4 colunas: sobram 22 colunas livres)
  AGAP=14     # distancia entre os alienigenas (sobram 10 colunas livres entre eles)
  ALNC=(5 6 7) # colunas de cada invader: lula (10 px), caranguejo (12 px) e polvo (14 px)
  FGAP=10      # distancia entre os ventiladores (cada um tem 4 colunas: sobram 6 colunas livres entre eles)
  SGAP=40      # distancia entre o ultimo ventilador (4 colunas) e a nave que vem atras deles: sobram 36 colunas livres
  FANSTEP=2    # ticks (0.1s) por quadro de giro do ventilador (2 = troca a cada 0.2s; 1 = giro mais rapido)
  SHNC=10      # colunas da nave + fogo (8 da nave, da altura do Pac-Man, + 2 do fogo atras)
  BSPD=6       # colunas por tick dos tiros (bem mais rapidos que os ventiladores e a nave)
  FIRE=2       # ticks entre um tiro e o proximo
  FIRE_ADV=14  # colunas ANTES da metade da tela em que a nave ja comeca a atirar (0 = so na metade)
  # a nave anda na MESMA velocidade dos ventiladores (1 coluna por tick), sem acelerar: a distancia dela para os ventiladores nunca muda
  FEXT=6       # ticks de explosao (3 quadros de 2 ticks)
  # (o desenho S+bandeira, FLG=1, fica centrado na faixa a esquerda do START e some quando o carro azul encosta nele)
  # MODE 3: os 3 ventiladores (girando) cruzam da direita para a esquerda, com a nave atras deles.
  #         FP = coluna da esquerda do ventilador da frente (os outros vem atras, a direita); SP = coluna da esquerda da nave;
  #         FA[k] = 1 ventilador vivo; FEX[k] = ticks de explosao que faltam; BX = colunas dos tiros no ar.
  draw_actors() {
    local i f s
    if [ "$MODE" = 0 ]; then
      for i in 2 1 0; do
        s=O; if [ $(((BT+i*7)%20)) -ge 18 ]; then s=S; fi   # cada monstro pisca a cada 2s (2 ticks), defasados
        draw_mv "M$((i+1))_$s" 4 $((PP-MOFF-i*MGAP)) R
      done
      if [ "$MOUTH" = 0 ]; then draw_mv PAC_R 4 "$PP" R; else draw_mv PAC_C 4 "$PP" R; fi
    elif [ "$MODE" = 1 ]; then
      if [ "$HALF" != 1 ]; then   # (bandeira e fumaca ficam paradas: so redesenha no passo inteiro)
        [ "$FLG" = 1 ] && draw_spr FLAG 6 $(( (TW1-6)/2 ))   # centrado entre a borda esquerda da tela e o START
        for i in "${!SMK_V[@]}"; do   # fumaca: nasce acesa e pisca (acesa / apagada) 3 vezes ate acabar a vida
          if [ $(( ((SMOKE_LIFE-SMK_L[i])/SMOKE_BLINK) % 2 )) -eq 0 ]; then draw_spr SMOKE 4 "${SMK_V[i]}"
          else for ((f=0; f<4; f++)); do erase_cell $((SMK_V[i]+f)); done; fi
        done
      fi
      draw_mv CAR_B 5 "$CP" L
      draw_mv CAR_R 5 "$RP" L
    elif [ "$MODE" = 2 ]; then
      f=$(( (BT/3)%2 + 1 ))                          # troca de quadro a cada 0.3s
      for i in 0 1 2; do
        s=O; if [ $(((BT+i*7)%20)) -ge 18 ]; then s=S; fi   # cada invader pisca a cada 2s, defasados
        draw_mv "AL$((i+1))_${f}_$s" "${ALNC[i]}" $((AP-i*AGAP)) R
      done
    else
      for i in 0 1 2; do
        if [ "${FA[i]}" = 1 ]; then
          f=$(( (BT/FANSTEP + i) % 2 ))              # alterna os 2 quadros de giro (defasados entre os ventiladores)
          draw_mv "FAN_$f" 4 $((FP+i*FGE)) L
        elif [ "${FEX[i]}" -gt 0 ]; then             # foi atingido: explosao de 3 quadros
          draw_mv "EXP_$(( (FEXT-FEX[i])/2 ))" 4 $((FP+i*FGE)) L
        fi
      done
      draw_mv "FLM_$((BT%3))" 2 $((SP+8)) L          # fogo do motor, atras (a direita) da nave (antes da nave: no meio passo as duas se tocam)
      draw_mv SHIP 8 "$SP" L                         # a nave vem atras do ultimo ventilador
      for i in "${BX[@]}"; do draw_bul "$i"; done    # tiros
    fi
  }
  draw_scan() {   # redesenho completo das duas trilhas
    [ "$TRK_OK" = 1 ] || return
    if [ "$MODE" = 0 ]; then
      DOTS1="$(make_dots "$TW1")"; DOTS2="$(make_dots "$TW2")"
      draw_dots
    else
      clear_track
    fi
    draw_actors
  }
  smoke_step() {   # envelhece as baforadas (apaga as que acabaram) e solta uma nova atras do carro vermelho (maximo SMOKE_N no total)
    local i j v l nv=() nl=() tot=$((TW1+TW2))
    for i in "${!SMK_V[@]}"; do
      v=${SMK_V[i]}; l=$((SMK_L[i]-1))
      if [ "$l" -le 0 ]; then for ((j=0; j<4; j++)); do erase_cell $((v+j)); done; continue; fi   # terminou as 3 piscadas: some
      nv+=("$v"); nl+=("$l")
    done
    [ "$SMK_CD" -gt 0 ] && SMK_CD=$((SMK_CD-1))
    if [ "$SMK_N" -lt "$SMOKE_N" ] && [ "$SMK_CD" -le 0 ] && [ $((RP+2)) -le $((tot/2)) ] && [ $((RP+8)) -gt 0 ]; then   # so comeca quando o centro do carro chega na metade da tela
      nv+=($((RP+5))); nl+=("$SMOKE_LIFE"); SMK_CD=$SMOKE_EVERY; SMK_N=$((SMK_N+1))   # sai logo atras (a direita) do carro vermelho e fica parada
    fi
    SMK_V=("${nv[@]}"); SMK_L=("${nl[@]}")
  }
  scan_half() {   # meio passo: redesenha so o que anda, deslocado 1 pixel
    [ "$TRK_OK" = 1 ] || return
    [ "$WAIT" -gt 0 ] && return
    HALF=1; draw_actors; HALF=0
  }
  scan_tick() {
    [ "$TRK_OK" = 1 ] || return
    local tot=$((TW1+TW2)) j
    BT=$((BT+1)); MOUTH=$((1-MOUTH))
    if [ "$WAIT" -gt 0 ]; then WAIT=$((WAIT-1)); draw_actors; return; fi
    if [ "$MODE" = 0 ]; then
      if [ "$PP" -ge $((tot+MOFF+2*MGAP)) ]; then   # o ultimo monstro tambem ja saiu: vez dos carros
        MODE=1; CP=$tot; WAIT=3; SMK_V=(); SMK_L=(); SMK_CD=0; SMK_N=0
        RP=$((tot+RGAP))
        clear_track
        FLG=0; [ "$TW1" -ge 9 ] && FLG=1        # so desenha se couber a esquerda do START
        [ "$FLG" = 1 ] && draw_spr FLAG 6 $(( (TW1-6)/2 ))
        return
      fi
      erase_cell "$PP"; for j in 0 1 2; do erase_cell $((PP-MOFF-j*MGAP)); done
      PP=$((PP+1))
    elif [ "$MODE" = 1 ]; then
      if [ $((RP+5)) -le 0 ] && [ "${#SMK_V[@]}" -eq 0 ]; then   # o carro vermelho saiu e a fumaca acabou: vez dos alienigenas
        MODE=2; AP=-7; WAIT=3
        clear_track
        return
      fi
      local ncp=$((CP-CSTEP)) nrp=$((RP-RSTEP))
      [ "$nrp" -lt $((ncp+RMIN)) ] && nrp=$((ncp+RMIN))    # o vermelho (mais rapido) alcanca o azul, mas nao encosta
      for ((j=ncp+5; j<=CP+4; j++)); do erase_cell "$j"; done
      for ((j=nrp+5; j<=RP+4; j++)); do erase_cell "$j"; done
      CP=$ncp; RP=$nrp
      smoke_step
      if [ "$FLG" = 1 ] && [ "$CP" -le $(( (TW1-6)/2 + 5 )) ]; then   # a frente do carro azul encostou no desenho: ele some
        FLG=0
        for ((j=(TW1-6)/2; j<=(TW1-6)/2+5; j++)); do erase_cell "$j"; done
      fi
    elif [ "$MODE" = 2 ]; then
      if [ $((AP-2*AGAP)) -ge "$tot" ]; then   # o ultimo alienigena saiu: vez dos ventiladores
        MODE=3; FP=$tot; WAIT=3
        FA=(1 1 1); FEX=(0 0 0); BX=(); BCD=0; FGE=$FGAP; SGE=$SGAP
        # a nave so atira na metade da tela e anda na mesma velocidade dos ventiladores (distancia constante): para o ventilador da frente ainda
        # estar na tela (com folga de 10 colunas) quando a nave chegar na metade, 2*FGE+SGE nao pode passar de tot/2-14.
        # Se couber, usa FGAP/SGAP; em telas mais estreitas reduz as duas distancias na mesma proporcao.
        j=$((tot/2-14))
        if [ "$j" -lt $((2*FGAP+SGAP)) ]; then
          [ "$j" -lt 20 ] && j=20
          FGE=$((FGAP*j/(2*FGAP+SGAP))); SGE=$((SGAP*j/(2*FGAP+SGAP)))
          [ "$FGE" -lt 6 ] && FGE=6
        fi
        SP=$((FP+2*FGE+SGE))                      # a nave entra atras dos ventiladores
        return
      fi
      for j in 0 1 2; do erase_cell $((AP-j*AGAP)); done
      AP=$((AP+1))
    else
      local k b nb nx tg na=0 step=1
      if [ $((SP+SHNC)) -le 0 ]; then                   # a nave saiu pela esquerda: bolinhas voltam
        MODE=0; PP=-4; WAIT=3; BX=()
        draw_dots
        return
      fi
      # (a nave nao acelera: step fica sempre 1, igual aos ventiladores)
      # 1) tudo anda para a esquerda: ventiladores e nave 1 coluna por tick (mesma velocidade)
      for k in 0 1 2; do
        if [ "${FA[k]}" = 1 ] || [ "${FEX[k]}" -gt 0 ]; then erase_cell $((FP+k*FGE+3)); fi
      done
      for ((j=0; j<step; j++)); do erase_cell $((SP+SHNC-1-j)); done
      FP=$((FP-1)); SP=$((SP-step))
      for k in 0 1 2; do   # (seguranca) ventilador que sair da tela sem ser atingido some sem explodir
        if [ "${FA[k]}" = 1 ] && [ $((FP+k*FGE+3)) -lt 0 ]; then FA[k]=0; fi
      done
      # 2) explosoes: avancam um quadro e, no fim, apagam o lugar do ventilador
      for k in 0 1 2; do
        if [ "${FEX[k]}" -gt 0 ]; then
          FEX[k]=$((FEX[k]-1))
          if [ "${FEX[k]}" = 0 ]; then for ((j=0; j<4; j++)); do erase_cell $((FP+k*FGE+j)); done; fi
        fi
      done
      # 3) tiros: andam para a esquerda e acertam o ventilador vivo mais proximo da nave
      nb=()
      for b in "${BX[@]}"; do
        erase_mid "$b"; erase_mid $((b+1))
        nx=$((b-BSPD)); tg=-1
        for k in 2 1 0; do if [ "${FA[k]}" = 1 ]; then tg=$k; break; fi; done
        if [ "$tg" -ge 0 ]; then
          if [ "$nx" -le $((FP+tg*FGE+3)) ]; then FA[tg]=0; FEX[tg]=$FEXT; continue; fi   # acertou: explode
        elif [ "$nx" -lt -1 ]; then continue; fi
        nb+=("$nx")
      done
      BX=("${nb[@]}")
      # 4) novo tiro: assim que o centro da nave chega na METADE da tela (e dai em diante) e se ainda ha ventiladores sem tiro a caminho
      na=0; for k in 0 1 2; do [ "${FA[k]}" = 1 ] && na=$((na+1)); done
      if [ "$BCD" -gt 0 ]; then BCD=$((BCD-1)); fi
      if [ "$BCD" -le 0 ] && [ "$na" -gt "${#BX[@]}" ] && [ $((SP+4)) -le $((tot/2+FIRE_ADV)) ]; then   # comeca a atirar FIRE_ADV colunas antes da metade da tela
        BX+=($((SP-2))); BCD=$FIRE
      fi
    fi
    draw_actors
  }

  # ===== Add/Remove (botao X do controle / tecla X): janela menor por cima do menu, 2 colunas: SYSTEMS | FILES =====
  # SYSTEMS: marcado [X] = sistema REMOVIDO do ZipMenu (entra em $EXCL, igual ao "echo sistema >> zipmenu-exclude.txt";
  #          desmarcar = tira a linha do arquivo). FILES: marcado [X] = extensao OCULTA da lista de arquivos do zip
  #          (fica em $HIDEEXT, uma por linha, sem ponto). Tudo e gravado na hora, a cada marca/desmarca.
  EXTS_DEF=(
    txt png jpg jpeg bmp doc exe bat rar 2mg 32x 3ds 3dsx 669 68k 7z 88d a26 a52 a78 adf adz agb app
    arduboy atr atx avi bas bin bs c8 car cas cbz ccc ccd cci cdi cdt ch8 chd chf chip8 cia ciso col
    com conf cpr crt cso ctr cue cvs cxi d1m d2m d4m d64 d6z d71 d7z d80 d81 d82 d88 d8z dat dcm dim
    dir dmk dms do dol dosz dsi dsk dump dup ecm elf far fd fdi fds fig flac g g41 g4z g64 g6z game
    gb gba gbc gcm gcz gdi gen gg gif gw gz hdd hdf hdi hdm hdr hdv hdz hex ima img int ipf iso it
    j64 jag jar k7 lha lnx love lst lua lyx lzh m3u m5 m7 md mdf mds mgd mgw min mkv mod mp3 mp4 msa
    mtm mx mx1 mx2 n64 nbz nca ndd nds nes nfd ngc ngp ngpc nhd nib npc nrg nro nsf nsfe nso nsp o2
    ogg p00 p8 pak pbp pc pce pco pdf pgm pic po ppm prg psd qd rom rpk rpx rvz rzx s3m sap sc scl
    scummvm sdi sf7 sfc sg sgb sgd sgx sh smc smd sms sna squashfs srl st stc stm stx sub sv svm swc
    szx t64 tap tcrt tfd tga tgc tic toc trd tvc tzx u64 uae unf unif uze v32 v64 vb vdk vec vfd vfl
    voc vsf wad wasm wav wbfs webm wia woz ws wsc wua wud wux x64 x6z xci xdf xex xfd xiso xm z64
    z80 zar zip zso
  )   # extensoes da coluna FILES: as 9 primeiras (txt..rar) e depois as de ROM/midia que os emuladores do Batocera aceitam (A-Z). Para ter outra: acrescente aqui
  declare -A SYSX=() EXTX=()
  SYSL=(); EXTL=(); ARCOL=0; ARTOP=(0 0); ARSEL=(0 0)
  AR_SELBG="48;2;90;0;140"; AR_DIMBG="48;2;40;40;90"   # AR_SELBG = cabecalho da coluna ativa; AR_DIMBG = item marcado na coluna inativa
  AR_BODY="40"   # fundo da janelinha (preto, igual ao da lista de fora; para azul escuro: 48;2;0;0;60)
  ARTH=(1 1); ARTP=(0 0)   # tamanho/posicao do "thumb" da barra de rolagem de cada coluna

  ar_set() {   # $1 = arquivo  $2 = linha  $3 = 1 (acrescenta) | 0 (remove a linha exata)
    local f="$1" v="$2"
    if [ "$3" = 1 ]; then
      mkdir -p "$(dirname "$f")" 2>/dev/null
      [ -s "$f" ] && [ -n "$(tail -c1 "$f" 2>/dev/null)" ] && echo >> "$f"
      printf '%s\n' "$v" >> "$f"
    elif [ -f "$f" ]; then
      grep -vxF -- "$v" "$f" > "$f.tmp"; mv -f "$f.tmp" "$f"
    fi
  }

  ar_load() {
    local d e x
    local -a all=()
    SYSL=(); EXTL=(); SYSX=(); EXTX=()
    for d in /userdata/roms/*/; do d="${d%/}"; all+=("${d##*/}"); done
    if [ -s "$EXCL" ]; then
      while IFS= read -r d || [ -n "$d" ]; do
        d="${d//$'\r'/}"; [ -n "$d" ] || continue
        SYSX[$d]=1; all+=("$d")   # sistema excluido sem pasta em /userdata/roms tambem aparece (para poder desmarcar)
      done < "$EXCL"
    fi
    mapfile -t SYSL < <(printf '%s\n' "${all[@]}" | grep -v '^$' | LC_ALL=C sort -fu)
    EXTL=("${EXTS_DEF[@]}")
    if [ -s "$HIDEEXT" ]; then
      while IFS= read -r e || [ -n "$e" ]; do
        e="${e//[$'\r ']/}"; e="${e#.}"; e="${e,,}"; [ -n "$e" ] || continue
        EXTX[$e]=1
        x=0; for d in "${EXTL[@]}"; do [ "$d" = "$e" ] && x=1; done
        [ "$x" = 1 ] || EXTL+=("$e")
      done < "$HIDEEXT"
    fi
  }

  ar_toggle() {   # $1 = coluna (0 sistemas, 1 arquivos)  $2 = indice
    local c="$1" i="$2" n
    if [ "$c" = 0 ]; then
      n="${SYSL[i]}"; [ -n "$n" ] || return
      if [ -n "${SYSX[$n]}" ]; then SYSX[$n]=""; ar_set "$EXCL" "$n" 0; else SYSX[$n]=1; ar_set "$EXCL" "$n" 1; fi
    else
      n="${EXTL[i]}"; [ -n "$n" ] || return
      if [ -n "${EXTX[$n]}" ]; then EXTX[$n]=""; ar_set "$HIDEEXT" "$n" 0; else EXTX[$n]=1; ar_set "$HIDEEXT" "$n" 1; fi
    fi
  }

  ar_calc() {   # tamanho/posicao da janelinha (relativo a janela do menu)
    PW=$(( W*72/100 )); [ "$PW" -lt 40 ] && PW=40; [ "$PW" -gt $((W-2)) ] && PW=$((W-2))
    PH=$(( H*70/100 )); [ "$PH" -lt 12 ] && PH=12; [ "$PH" -gt $((H-2)) ] && PH=$((H-2))
    PX=$(( X0 + (W-PW)/2 )); PY=$(( Y0 + (H-PH)/2 ))
    LW=$(( (PW-3)/2 )); RW=$(( PW-3-LW ))
    LR=$(( PH-4 ))   # linhas da lista: titulo(0) cabecalho(1) lista(2..) dica(PH-2) borda(PH-1)
  }

  ar_row() {   # $1 = coluna  $2 = linha visivel
    local c="$1" k="$2" idx x w n name st bg
    if [ "$c" = 0 ]; then x=$((PX+1)); w=$LW; n=${#SYSL[@]}; else x=$((PX+2+LW)); w=$RW; n=${#EXTL[@]}; fi
    idx=$(( ARTOP[c] + k ))
    bg="$AR_BODY"
    if [ "$idx" -eq "${ARSEL[c]}" ]; then if [ "$ARCOL" = "$c" ]; then bg="$SEL_BG"; else bg="$AR_DIMBG"; fi; fi   # SEL_BG = a mesma cor pulsante (roxo<->verde) da barra de fora
    at $((PY+2+k)) "$x"; printf '\e[0;97;%sm\e[%dX' "$bg" "$w"
    # barra de rolagem: ultima coluna de cada lista (▓ thumb / ░ trilho)
    if [ "$k" -ge "${ARTP[c]}" ] && [ "$k" -lt $(( ARTP[c]+ARTH[c] )) ]; then
      printf '\e[%d;%dH\e[1;97;%sm\xe2\x96\x88' $((PY+2+k)) $((x+w-1)) "$AR_BODY"
    else
      printf '\e[%d;%dH\e[0;38;2;60;60;170;%sm\xe2\x96\x91' $((PY+2+k)) $((x+w-1)) "$AR_BODY"
    fi
    [ "$idx" -ge "$n" ] && return
    if [ "$c" = 0 ]; then
      name="${SYSL[idx]}"; st=0; [ -n "${SYSX[$name]}" ] && st=1
    else
      name=".${EXTL[idx]}"; st=0; [ -n "${EXTX[${EXTL[idx]}]}" ] && st=1
    fi
    name="${name:0:$((w-7))}"
    at $((PY+2+k)) $((x+1))
    if [ "$st" = 1 ]; then printf '\e[1;91;%sm[X] \e[1;97;%sm%s' "$bg" "$bg" "$name"
    else printf '\e[1;92;%sm[ ] \e[0;97;%sm%s' "$bg" "$bg" "$name"; fi
  }

  ar_draw() {
    local r c k n x w t hb
    at "$PY" "$PX"; printf '\e[0;97;44m\e[%dX' "$PW"
    t=" ADD / REMOVE "; at "$PY" $((PX+(PW-${#t})/2)); printf '\e[1;97;44m%s' "$t"
    for ((r=1; r<=PH-2; r++)); do
      at $((PY+r)) "$PX"; printf '\e[0;97;44m \e[0;97;%sm\e[%dX' "$AR_BODY" $((PW-2))
      at $((PY+r)) $((PX+PW-1)); printf '\e[0;97;44m '
      [ "$r" -lt $((PH-2)) ] && { at $((PY+r)) $((PX+1+LW)); printf '\e[0;94;%sm\xe2\x94\x82' "$AR_BODY"; }
    done
    at $((PY+PH-1)) "$PX"; printf '\e[0;97;44m\e[%dX' "$PW"
    for c in 0 1; do
      if [ "$c" = 0 ]; then x=$((PX+1)); w=$LW; t="SYSTEMS"; n=${#SYSL[@]}; else x=$((PX+2+LW)); w=$RW; t="FILES"; n=${#EXTL[@]}; fi
      if [ "$ARCOL" = "$c" ]; then hb="$AR_SELBG"; else hb="$AR_BODY"; fi
      at $((PY+1)) "$x"; printf '\e[1;38;2;230;210;90;%sm\e[%dX' "$hb" "$w"
      at $((PY+1)) $((x+(w-${#t})/2)); printf '\e[1;38;2;230;210;90;%sm%s' "$hb" "$t"
      [ "${ARSEL[c]}" -lt "${ARTOP[c]}" ] && ARTOP[c]=${ARSEL[c]}
      [ "${ARSEL[c]}" -ge $((ARTOP[c]+LR)) ] && ARTOP[c]=$(( ARSEL[c]-LR+1 ))
      [ "${ARTOP[c]}" -lt 0 ] && ARTOP[c]=0
      if [ "$n" -gt "$LR" ]; then
        ARTH[c]=$(( LR*LR/n )); [ "${ARTH[c]}" -lt 1 ] && ARTH[c]=1
        ARTP[c]=$(( ARTOP[c]*(LR-ARTH[c])/(n-LR) ))
      else ARTH[c]=$LR; ARTP[c]=0; fi
      for ((k=0; k<LR; k++)); do ar_row "$c" "$k"; done
    done
    t="[X]=REMOVE  ENTER=SELECT  ESC=CLOSE"
    at $((PY+PH-2)) $((PX+(PW-${#t})/2))
    printf '\e[1;91;%sm[X]\e[0;37;%sm=REMOVE  \e[1;97;%smENTER\e[0;37;%sm=SELECT  \e[1;97;%smESC\e[0;37;%sm=CLOSE' "$AR_BODY" "$AR_BODY" "$AR_BODY" "$AR_BODY" "$AR_BODY" "$AR_BODY"
  }

  ar_pulse() {   # um passo da cor pulsante (mesma formula do pulse_tick de fora)
    local t
    PULSE=$(( (PULSE+1) % (2*PSTEPS) ))
    if [ "$PULSE" -le "$PSTEPS" ]; then t=$PULSE; else t=$((2*PSTEPS-PULSE)); fi
    SEL_BG="48;2;$(( 22-22*t/PSTEPS ));$(( 35*t/PSTEPS ));$(( 38-38*t/PSTEPS ))"
  }
  ar_selrows() {   # redesenha so a linha selecionada de cada coluna (animacao da cor)
    local c k
    for c in 0 1; do k=$(( ARSEL[c]-ARTOP[c] )); [ "$k" -ge 0 ] && [ "$k" -lt "$LR" ] && ar_row "$c" "$k"; done
  }

  addremove() {
    local K K2 n c rc
    ar_load; ar_calc
    ARCOL=0; ARTOP=(0 0); ARSEL=(0 0)
    { printf '\e[?2026h'; ar_draw; printf '\e[?2026l'; } > "$TICKBUF"; cat "$TICKBUF"
    while true; do
      IFS= read -rsn1 -t 0.3 K; rc=$?   # a cada 0.3s sem tecla: um passo da cor pulsante (igual a barra de fora)
      if [ "$rc" -gt 128 ]; then
        ar_pulse; { printf '\e[?2026h'; ar_selrows; printf '\e[?2026l'; } > "$TICKBUF"; cat "$TICKBUF"
        continue
      elif [ "$rc" -ne 0 ]; then break; fi
      c=$ARCOL
      if [ "$c" = 0 ]; then n=${#SYSL[@]}; else n=${#EXTL[@]}; fi
      if [ "$K" = $'\e' ]; then
        IFS= read -rsn2 -t 0.05 K2
        case "$K2" in
          '[A') [ "$n" -gt 0 ] && ARSEL[c]=$(( (ARSEL[c]-1+n) % n )) ;;
          '[B') [ "$n" -gt 0 ] && ARSEL[c]=$(( (ARSEL[c]+1) % n )) ;;
          '[D') ARCOL=0 ;;
          '[C') ARCOL=1 ;;
          '[5') IFS= read -rsn1 -t 0.05 _; ARSEL[c]=$(( ARSEL[c]-LR+1 )); [ "${ARSEL[c]}" -lt 0 ] && ARSEL[c]=0 ;;
          '[6') IFS= read -rsn1 -t 0.05 _; ARSEL[c]=$(( ARSEL[c]+LR-1 )); [ "${ARSEL[c]}" -ge "$n" ] && ARSEL[c]=$((n-1)); [ "${ARSEL[c]}" -lt 0 ] && ARSEL[c]=0 ;;
          '') break ;;   # Esc / BACK fecha a janelinha
        esac
      elif [ "$K" = $'\x7f' ] || [ "$K" = $'\b' ] || [ "$K" = x ] || [ "$K" = X ]; then
        break   # Backspace ou X de novo tambem fecham
      elif [ -z "$K" ] || [ "$K" = $'\r' ] || [ "$K" = ' ' ]; then
        ar_toggle "$c" "${ARSEL[c]}"   # Enter / botao A: marca ou desmarca
      fi
      if read -rsn0 -t 0 2>/dev/null; then continue; fi
      { printf '\e[?2026h'; ar_draw; printf '\e[?2026l'; } > "$TICKBUF"; cat "$TICKBUF"
    done
    # a lista de arquivos pode ter mudado (extensoes ocultas): refiltra e volta para a raiz do zip
    apply_filter; CUR=""; build_list; SEL=0; TOP=0; MQ_SEL=-1
  }

  SEL=0; TOP=0
  # marquee: nome grande do item selecionado anda da direita para a esquerda,
  # pausa no fim, volta ao comeco, pausa e repete
  MQ_SEL=-1; MQ_OFF=0; MQ_WAIT=15; MQ_T=0
  marquee_tick() {
    local name="${FILES[$SEL]}" vw=$((IW-4)) max k
    max=$(( ${#name} - vw ))
    [ "$max" -gt 0 ] || return
    [ "$MQ_OFF" -gt "$max" ] && MQ_OFF=$max
    if [ "$MQ_WAIT" -gt 0 ]; then MQ_WAIT=$((MQ_WAIT-1)); return; fi
    if [ "$MQ_OFF" -ge "$max" ]; then
      MQ_OFF=0; MQ_WAIT=15
    else
      MQ_T=$((MQ_T+1))
      [ $((MQ_T%2)) -eq 0 ] || return   # 1 caractere a cada 0.2s
      MQ_OFF=$((MQ_OFF+1))
      [ "$MQ_OFF" -ge "$max" ] && MQ_WAIT=15
    fi
    k=$((SEL-TOP))
    [ "$k" -lt 0 ] || [ "$k" -ge "$L" ] && return
    row $((Y0+LOFF+k)) "$SEL" 1
    scrollbar_cell "$k"
    draw_pulse
  }
  draw() {
    local k idx s pct ps
    if [ "$SEL" != "$MQ_SEL" ]; then MQ_SEL=$SEL; MQ_OFF=0; MQ_WAIT=15; MQ_T=0; fi
    if [ "$SEL" -lt "$TOP" ]; then TOP=$SEL; fi
    if [ "$SEL" -ge $((TOP+L)) ]; then TOP=$((SEL-L+1)); fi
    if [ $((TOP+L)) -gt "$N" ]; then TOP=$((N-L)); fi
    if [ "$TOP" -lt 0 ]; then TOP=0; fi
    # calcula o thumb da scrollbar para este redesenho
    if [ "$N" -gt "$L" ]; then
      THUMB_H=$(( L*L/N )); [ "$THUMB_H" -lt 1 ] && THUMB_H=1
      THUMB_POS=$(( TOP*(L-THUMB_H)/(N-L) ))
    else
      THUMB_H=$L; THUMB_POS=0
    fi
    for ((k=0; k<L; k++)); do
      idx=$((TOP+k)); s=0; [ "$idx" -eq "$SEL" ] && s=1
      row $((Y0+LOFF+k)) "$idx" "$s"
      scrollbar_cell "$k"
    done
    at $((Y0+LOFF-1)) $((X0+1)); printf '\e[0;97;40m\e[%dX' "$IW"   # linha de folga entre o cabecalho e a lista
    at $((Y0+H-5)) $((X0+1)); printf '\e[0;97;40m\e[%dX' "$IW"   # linha de folga entre a lista e a linha dos botoes
    # porcentagem da posicao, na area preta acima da lista (mesma linha dos botoes), alinhada a direita
    pct=$(( (SEL+1)*100/N ))
    if [ $((PCOL+4)) -le $((X0+W-1)) ]; then printf -v ps '%02d' "$pct"; at "$BROW" "$PCOL"; printf '\e[1;92;%sm%3s\e[1;97;%sm%%' "$BAR_BG" "$ps" "$BAR_BG"; fi
    draw_pulse
  }

  # spinner (braille) durante a extracao do arquivo escolhido do zip
  spinner_wait() {
    local pid="$1" i=0
    local frames=('\xe2\xa0\x8b' '\xe2\xa0\x99' '\xe2\xa0\xb9' '\xe2\xa0\xb8' '\xe2\xa0\xbc' \
                  '\xe2\xa0\xb4' '\xe2\xa0\xa6' '\xe2\xa0\xa7' '\xe2\xa0\x87' '\xe2\xa0\x8f')
    local n=${#frames[@]}
    while kill -0 "$pid" 2>/dev/null; do
      if [ $((PCOL+4)) -le $((X0+W-1)) ]; then
        at "$BROW" "$PCOL"; printf '\e[1;97;%sm%b   ' "$BAR_BG" "${frames[$((i%n))]}"
      fi
      i=$((i+1))
      sleep 0.08
    done
    wait "$pid" 2>/dev/null
  }

  TICKBUF=/tmp/zipmenu-tick.$$
  # SEM ECO do terminal: o "read -s" so desliga o eco enquanto esta lendo; entre uma leitura e outra (desenhando) o terminal
  # devolvia na tela as teclas que chegavam (ex.: seta segurada = "^[[B") no lugar do cursor, perto da porcentagem.
  STTY_OLD=$(stty -g 2>/dev/null)
  stty -echo 2>/dev/null
  trap 'printf "\e[0m\e[2J\e[?25h"; rm -f "$TICKBUF"; [ -n "$STTY_OLD" ] && stty "$STTY_OLD" 2>/dev/null' EXIT
  frame; draw
  RESULT=""; OR=$R; OC=$C; TK=0
  # cadencia FIXA: o proximo tick e marcado por relogio (EPOCHREALTIME), entao o tempo gasto desenhando/lendo teclas nao
  # atrasa a animacao (antes: cada volta esperava 0.1s DEPOIS de desenhar = passos irregulares e mais lentos).
  # TICK_US = microssegundos entre passos (100000 = 0.1s, como antes; menor = mais rapido).
  TICK_US=50000   # meio passo (0,05s): a cada 2 ticks anda 1 coluna (igual a antes, 0,1s) e no tick do meio desenha o meio passo
  NEXT=$(( ${EPOCHREALTIME/[.,]/} + TICK_US )) 2>/dev/null || NEXT=0
  while true; do
    TO=0.1
    if [ -n "$EPOCHREALTIME" ]; then
      NOW=${EPOCHREALTIME/[.,]/}; WT=$((NEXT-NOW))
      [ "$WT" -lt 1000 ] && WT=1000
      [ "$WT" -gt "$TICK_US" ] && WT=$TICK_US
      printf -v TO '0.%06d' "$WT"
    fi
    IFS= read -rsn1 -t "$TO" K; RC=$?
    if [ "$RC" -gt 128 ]; then
      if [ -n "$EPOCHREALTIME" ]; then
        NEXT=$((NEXT+TICK_US)); NOW=${EPOCHREALTIME/[.,]/}
        [ "$NEXT" -lt "$NOW" ] && NEXT=$((NOW+TICK_US/2))   # ficou para tras: nao tenta "recuperar" varios passos de uma vez
      fi
      # nenhuma tecla: a cada tick anda a animacao e o letreiro; a cada 3 ticks pulsa a seta do item selecionado;
      # a cada 10 ticks (1s) confere se o terminal mudou de tamanho (o "stty size" cria um processo: era a cada 0.3s e
      # fazia um soluco na animacao)
      SUB=$((1-SUB))
      if [ "$SUB" = 0 ]; then   # tick do MEIO passo: so redesenha os sprites que andam, 1 pixel adiante
        { printf '\e[?2026h'; scan_half; printf '\e[?2026l'; } > "$TICKBUF"
        cat "$TICKBUF"
        continue
      fi
      TK=$((TK+1))
      # tudo do tick vai para um buffer e sai em UMA escrita so, dentro de atualizacao sincronizada:
      # sem isso o xterm repinta entre o apagar e o desenhar de cada sprite (piscadas, piores com a fonte grande)
      { printf '\e[?2026h'; scan_tick; marquee_tick; [ $((TK%3)) -eq 0 ] && pulse_tick; printf '\e[?2026l'; } > "$TICKBUF"
      cat "$TICKBUF"
      if [ $((TK%10)) -eq 0 ]; then
        layout
        if [ "$R" != "$OR" ] || [ "$C" != "$OC" ]; then
          OR=$R; OC=$C; frame; draw
        fi
      fi
      continue
    elif [ "$RC" -ne 0 ]; then
      break
    fi
    if [ "$K" = $'\e' ]; then
      IFS= read -rsn2 -t 0.05 K2
      case "$K2" in
        '[A') SEL=$(( (SEL-1+N) % N )) ;;
        '[B') SEL=$(( (SEL+1) % N )) ;;
        '[D') nav_up ;;      # seta esquerda: sobe uma pasta
        '[C') nav_down ;;    # seta direita: entra na pasta selecionada
        '[5') IFS= read -rsn1 -t 0.05 _; SEL=$(( SEL-L+1 )); [ "$SEL" -lt 0 ] && SEL=0 ;;
        '[6') IFS= read -rsn1 -t 0.05 _; SEL=$(( SEL+L-1 )); [ "$SEL" -ge "$N" ] && SEL=$((N-1)) ;;
        '') # Esc / BACK: dentro de uma pasta volta para a RAIZ do zip; na raiz fecha o menu
            if [ -n "$CUR" ]; then
              top="${CUR%%/*}/"; CUR=""; build_list; SEL=0; TOP=0; MQ_SEL=-1
              for i in "${!FILES[@]}"; do if [ "${FILES[i]}" = "$top" ]; then SEL=$i; break; fi; done
            else
              break
            fi ;;
      esac
      # tecla segurada: se ja tem mais teclas na fila, so move a selecao e redesenha uma vez no fim (evita piscar)
      if read -rsn0 -t 0 2>/dev/null; then continue; fi
      # a lista inteira sai em UMA escrita, dentro de atualizacao sincronizada (sem repintar linha por linha)
      { printf '\e[?2026h'; draw; printf '\e[?2026l'; } > "$TICKBUF"
      cat "$TICKBUF"
    elif [ "$K" = $'\x7f' ] || [ "$K" = $'\b' ]; then   # Backspace: sobe uma pasta
      nav_up && { { printf '\e[?2026h'; draw; printf '\e[?2026l'; } > "$TICKBUF"; cat "$TICKBUF"; }
    elif [ "$K" = x ] || [ "$K" = X ]; then   # botao X do controle: janela Add/Remove por cima do menu
      addremove
      { printf '\e[?2026h'; frame; draw; printf '\e[?2026l'; } > "$TICKBUF"; cat "$TICKBUF"
    elif [ -z "$K" ] || [ "$K" = $'\r' ]; then
      if [ "${ISDIR[SEL]}" = 1 ]; then   # pasta (ou "../"): entra/sai em vez de escolher
        nav_down
        { printf '\e[?2026h'; draw; printf '\e[?2026l'; } > "$TICKBUF"; cat "$TICKBUF"
      else
        RESULT="${FULL[SEL]}"; break
      fi
    fi
  done

  if [ -n "$RESULT" ]; then
    # pre-extrai aqui mesmo (ainda no xterm do menu) mostrando o spinner.
    # Se falhar, nao tem problema: o launcher extrai de novo (fallback).
    PRE_EXTRACTED="$(dirname "$OUT")/$(basename "$RESULT")"
    unzip -p "$ZIP" "$RESULT" > "$PRE_EXTRACTED" 2>/tmp/zipmenu-extract.log &
    spinner_wait "$!"
    [ -s "$PRE_EXTRACTED" ] || rm -f "$PRE_EXTRACTED"
  fi
  # igual ao backup que funcionava: o menu devolve so o NOME escolhido (vazio = cancelou)
  printf '%s' "$RESULT" > "$OUT"
  touch "$OUT.ran"
  exit 0
fi

# modo lancamento (chamado pelo ES via emulatorlauncher)
ARGS=("$@")
ROM=""; IDX=-1; SYSTEM=""
for i in "${!ARGS[@]}"; do
  case "${ARGS[$i]}" in
    -rom)    IDX=$((i+1)); ROM="${ARGS[$IDX]}" ;;
    -system) SYSTEM="${ARGS[$((i+1))]}" ;;
  esac
done

TMP=/tmp/zipmenu
JOY=/userdata/system/zipmenu-joy.py

# musica de fundo do menu (em loop; para quando o menu fecha).
# A musica esta EMBUTIDA no fim deste script (base64, depois da linha #__ZIPMENU_MUSIC_BASE64__) e e
# extraida para /tmp na primeira vez. Se existir o arquivo abaixo, ele toma o lugar da musica embutida.
MUSIC=/userdata/system/zipmenu-music.mp3
MUSIC_EMB=/tmp/zipmenu-music-embutida.mp3
MUSIC_VOL=52   # 0-100 (era 70; baixado 35% = 45; aumentado 15% = 52)
FONT_SZ=23      # fonte do menu no xterm (era 20; 23 = +15%; 26 = +30%; o xterm tem um tamanho so para a tela inteira, entao o cabecalho e a lista usam o mesmo)
MLOG=/userdata/system/zipmenu-music.log   # diagnostico da musica (reescrito a cada abertura do menu)

# prepara o arquivo de musica (externo ou embutido) e tenta tocar em loop, em segundo plano.
# Tenta varios players/saidas de audio; um player que morre logo apos iniciar e descartado e o
# proximo e tentado. Tudo fica registrado em $MLOG.
start_music() {
  MPID=""
  {
    echo "== $(date) =="
    echo "PATH=$PATH"
    echo "XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR:-<vazio>}  USER=$(id -un 2>/dev/null)  DISPLAY=$DISPLAY"
    ls -ld /var/run/pipewire* /var/run/pulse* /run/user/* 2>&1 | head -8
  } > "$MLOG" 2>&1

  if [ ! -f "$MUSIC" ]; then
    if [ ! -s "$MUSIC_EMB" ]; then
      sed '1,/^#__ZIPMENU_MUSIC_BASE64__$/d' "$SELF" | base64 -d > "$MUSIC_EMB.tmp" 2>>"$MLOG" \
        && [ -s "$MUSIC_EMB.tmp" ] && mv -f "$MUSIC_EMB.tmp" "$MUSIC_EMB" || rm -f "$MUSIC_EMB.tmp"
    fi
    [ -s "$MUSIC_EMB" ] && MUSIC="$MUSIC_EMB"
  fi
  if [ ! -s "$MUSIC" ]; then echo "ERRO: sem arquivo de musica (extracao da embutida falhou)" >> "$MLOG"; return; fi
  echo "musica: $MUSIC ($(wc -c < "$MUSIC") bytes)" >> "$MLOG"

  export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/var/run}"
  local a cmd ao
  local -a aoarg
  for a in mpv mpv:alsa mpv:pulse mpv:pipewire ffplay cvlc mpg123 mplayer play; do
    cmd="${a%%:*}"; ao=""; [ "$a" != "$cmd" ] && ao="${a#*:}"
    if ! command -v "$cmd" >/dev/null 2>&1; then echo "$a: $cmd nao existe" >> "$MLOG"; continue; fi
    echo "tentando: $a" >> "$MLOG"
    case "$cmd" in
      mpv)
        aoarg=(); [ -n "$ao" ] && aoarg=(--ao="$ao")
        mpv --no-video --no-terminal --log-file="$MLOG.mpv" --msg-level=all=info \
            --loop-file=inf --volume="$MUSIC_VOL" "${aoarg[@]}" "$MUSIC" >/dev/null 2>&1 </dev/null & ;;
      ffplay)  ffplay -nodisp -loglevel warning -loop 0 -volume "$MUSIC_VOL" "$MUSIC" >>"$MLOG" 2>&1 </dev/null & ;;
      cvlc)    cvlc --no-video --loop --gain=0.52 "$MUSIC" >>"$MLOG" 2>&1 </dev/null & ;;
      mpg123)  mpg123 -q --loop -1 "$MUSIC" >>"$MLOG" 2>&1 </dev/null & ;;
      mplayer) mplayer -really-quiet -loop 0 -volume "$MUSIC_VOL" "$MUSIC" >>"$MLOG" 2>&1 </dev/null & ;;
      play)    play -q "$MUSIC" repeat 999 >>"$MLOG" 2>&1 </dev/null & ;;
    esac
    MPID=$!
    sleep 0.7
    if kill -0 "$MPID" 2>/dev/null; then echo "OK: tocando com $a (pid $MPID)" >> "$MLOG"; return; fi
    echo "$a morreu logo ao iniciar" >> "$MLOG"
    MPID=""
  done
  echo "NENHUM player funcionou" >> "$MLOG"
}

# so age nos sistemas da lista (e nunca em chamada recursiva)
if [ -z "$ZIPMENU_ACTIVE" ] && [ -n "$SYSTEM" ] && ! grep -qxF "$SYSTEM" "$EXCL" 2>/dev/null; then
  case "${ROM,,}" in
    *.zip)
      COUNT=$(unzip -Z1 "$ROM" 2>/dev/null | grep -vc '/$')
      if [ "$COUNT" -gt 1 ]; then
        rm -rf "$TMP"; mkdir -p "$TMP"
        export DISPLAY="${DISPLAY:-:0}"
        # ajudante de joystick: controle vira setas/Enter/Esc no menu
        JPID=""
        if [ -f "$JOY" ]; then
          python3 "$JOY" >/tmp/zipmenu-joy.log 2>&1 &
          JPID=$!
          sleep 0.5
        fi
        start_music   # (definida mais acima; deixa o diagnostico em /userdata/system/zipmenu-music.log)
        MPID="${MPID:-}"
        # o xterm abria pequeno (80x24 com a fonte grande) e so depois o gerenciador de janelas o colocava em tela cheia.
        # Agora ele ja nasce com o tamanho da tela (colunas/linhas = pixels da tela / pixels da celula, lidos do cache da
        # abertura anterior; na 1a vez usa um tamanho enorme, que o -fullscreen reduz para a tela), sem janela pequena visivel.
        GEOM=""
        SCR=$(xrandr 2>/dev/null | sed -n 's/.*current \([0-9]*\) x \([0-9]*\),.*/\1 \2/p' | head -1)
        read -r SW SH <<<"$SCR"
        read -r CCH CCW < "$CELLCACHE" 2>/dev/null
        if [ "${SW:-0}" -gt 0 ] && [ "${CCH:-0}" -gt 0 ] && [ "${CCW:-0}" -gt 0 ] 2>/dev/null; then
          GEOM="$((SW/CCW))x$((SH/CCH))+0+0"
        else
          GEOM="400x150+0+0"
        fi
        xterm -geometry "$GEOM" -fullscreen -bg black -fg white -fa Monospace -fs "$FONT_SZ" \
          -xrm 'XTerm*color4: #000087' \
          -xrm 'XTerm*allowWindowOps: true' \
          -xrm 'XTerm*disallowedWindowOps: 20,21,SetXprop,SetSelection' \
          -e "$SELF" --pick "$ROM" "$TMP/choice"
        if [ -n "$JPID" ]; then kill "$JPID" 2>/dev/null; fi
        if [ -n "$MPID" ]; then kill "$MPID" 2>/dev/null; wait "$MPID" 2>/dev/null; fi   # para a musica
        if [ -e "$TMP/choice.ran" ]; then
          if [ ! -s "$TMP/choice" ]; then rm -rf "$TMP"; exit 0; fi   # cancelou
          NAME=$(cat "$TMP/choice")
          EXTRACTED="$TMP/$(basename "$NAME")"
          # se o menu ja extraiu (com spinner), usa; senao extrai aqui (como no backup)
          if [ ! -s "$EXTRACTED" ]; then
            unzip -p "$ROM" "$NAME" > "$EXTRACTED" || { rm -rf "$TMP"; exit 1; }
          fi
          ARGS[$IDX]="$EXTRACTED"
        fi
      fi
      ;;
  esac
fi

export ZIPMENU_ACTIVE=1
"$REAL" "${ARGS[@]}"
RC=$?
rm -rf "$TMP"
exit $RC
